#!/data/data/com.termux/files/usr/bin/bash
# Кладёт проект Smart Proxy AI в твой репозиторий. Запуск: bash push-to-github.sh
# Нужен токен GitHub (Settings -> Developer settings -> Personal access tokens, право repo).
set -e
command -v git >/dev/null || pkg install -y git
command -v unzip >/dev/null || pkg install -y unzip
read -rp "Токен GitHub: " TOKEN
D=$(mktemp -d); cd "$D"
git clone "https://Kotenok-Rwka:${TOKEN}@github.com/Kotenok-Rwka/Smart-proxy-app-for-ai.git" repo 2>/dev/null || { mkdir repo; cd repo; git init -b main; git remote add origin "https://Kotenok-Rwka:${TOKEN}@github.com/Kotenok-Rwka/Smart-proxy-app-for-ai.git"; cd ..; }
cd repo
echo "" | base64 -d > ../p.zip
unzip -oq ../p.zip -d ..
cp -a ../smart-proxy-ai/. .
git add -A
git -c user.name="Kotenok-Rwka" -c user.email="noreply@users.noreply.github.com" commit -m "Initial Smart Proxy AI: injector, Compose UI, CI"
git branch -M main
git push -u origin main
echo "Готово. Открой вкладку Actions в репозитории."
